/**
 * Guards the short-and-confident prose contract on every surface that carries it: the
 * RFC-0001 readability paragraph, the JSDoc and comment rules in the four stack rule
 * templates, the PR-body and issue-body grammars, the reply length in pr-answer and
 * pr-resolve, the release-notes prompt, and the two pr-review checks that enforce it.
 * Byte-identity between the RFC and its copies is sharedBlockSync's job; this file
 * asserts the wording itself, so a rewrite that drifts back to narrative fails here.
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";

import { describe, expect, test } from "bun:test";

const actionDir = join(import.meta.dirname, "..");
const repoRoot = join(actionDir, "..", "..", "..");
const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");

const rulesPaths = [
  "rules/Bun.md",
  "rules/Bun+React+Tailwind.md",
  "rules/NodeJS+React.md",
  "rules/NodeJS+React+Tailwind.md",
].map((relative) => join(repoRoot, relative));

const readRepo = (relative: string) => readFile(join(repoRoot, relative), "utf8");
const readSkill = (relative: string) => readFile(join(skillsDir, relative), "utf8");

/** Slice of a markdown file between two headings, so a rule is asserted in its own section. */
function section(content: string, from: string, to: string): string {
  const start = content.indexOf(from);
  const end = content.indexOf(to, start);
  expect(start).toBeGreaterThan(-1);
  expect(end).toBeGreaterThan(start);
  return content.slice(start, end);
}

describe("RFC-0001 readability paragraph", () => {
  test("the block ends on the short-and-confident contract, not the old why-narrative", async () => {
    const rfc = await readRepo("rfc/0001-reference-formatting.md");
    const block = section(rfc, "<!-- ref-format:start -->", "<!-- ref-format:end -->");
    expect(block).toContain("Readability: write short and confident.");
